import type { HarmonicaAction, HarmonicaProfile } from "../harmonica/profile";
import { teachingNoteName, type NamingSystem } from "../music/naming";
import { HarmonicaBody } from "./HarmonicaBody";
import { breathStateForActions, slideStateForActions } from "./sliderState";
export function CompactHarmonicaView({profile,target,detected=[],feedback,showLabels=false,namingSystem="letters"}:{profile:HarmonicaProfile;target?:HarmonicaAction;detected?:HarmonicaAction[];feedback?:"correct"|"incorrect";showLabels?:boolean;namingSystem?:NamingSystem}){
 const detectedIds=new Set(detected.map(action=>action.id)),slider=slideStateForActions(detected.length?detected:target?[target]:[]),breath=breathStateForActions(detected.length?detected:target?[target]:[]);
 return <section className={`compact-harmonica-stage ${feedback??""}`} data-testid="compact-harmonica" data-profile={profile.id} data-slider={slider} data-breath={breath}><HarmonicaBody profile={profile} slider={slider} compact><div className="compact-holes">{Array.from({length:profile.holeCount},(_,i)=>i+1).map(hole=>{const targetHere=target?.hole===hole,found=detected.filter(action=>action.hole===hole);return <div key={hole} className={`compact-hole ${targetHere?"target":""} ${found.length?"detected":""}`} data-hole={hole}><span>{hole}</span><i/>{(targetHere||found.length>0)&&<b aria-hidden="true">{(found[0]?.breath??target?.breath)==="blow"?"↑":"↓"}</b>}</div>})}</div></HarmonicaBody><div className="compact-guidance">{target&&<span className="target-copy">Target · hole {target.hole} · {target.breath} · slide {target.slide}{showLabels?` · ${teachingNoteName(target.canonicalMidi,namingSystem)}`:""}</span>} {detected.length>0&&<span className="detected-copy">Detected · {detected.length} possible action{detected.length===1?"":"s"} · {breath} breath · slider {slider}</span>}</div></section>
}
